const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=c=>`${esc(c.type)} · ${esc(c.id)}`;
const valued=p=>p.outcome==='Executable'||p.outcome==='NegativeBuilderDelta';
const status=s=>`${esc(s.type)}${s.reason?' · '+esc(s.reason):''}${s.block?' · блок '+esc(s.block):''}`;
export function renderBackrun(run,block) {
 const c=run.scenario.scheduler?.backrun,panel=$('#backrun-panel');panel.hidden=!c;if(!c)return;
 const asset=esc(run.scenario.chain.fee_asset),report=block?.scheduler?.search;
 $('#backrun-config').innerHTML=`<h2>Поиск после видимой транзакции</h2><p>Каждый маршрут проверяется на одной копии parent state после доставленной victim. Условный net учитывает комиссии ответа, платежа и bid; фактический результат зависит от выбора builder.</p>${Object.entries(c.policies).map(([agent,p])=>`<p><strong>${esc(agent)}</strong> · ${esc(p.account)}<br>Размеры: ${p.inputs.map(esc).join(', ')} ${asset} · minimum net ${esc(p.minimum_net_profit)} · bid ${esc(p.bid)}<br>Реакция ${esc(p.reaction_delay)} s; lifetime ${esc(p.lifetime)} s; native prices ответа/платежа ${esc(p.resource_price)}/${esc(p.payment_price)}</p>`).join('')}<p class="hint">До ${c.limits.hops} hops, ${c.limits.candidates_per_round} кандидатов и ${c.limits.venue_checks} проверок venue за раунд. Только собственный капитал, полный маршрут без остатков.</p>`;
 if(!report){$('#backrun-result').innerHTML='<p class="muted">Запустите блок, чтобы увидеть разрешённые наблюдения и решения поиска.</p>';return;}
 const m=report.metrics;
 $('#backrun-result').innerHTML=`<div class="stats"><div class="stat"><span>Prefix / кандидаты</span><strong>${m.prefixes} / ${m.candidates}</strong></div><div class="stat"><span>Попытки members / venue checks</span><strong>${m.members} / ${m.venue_checks}</strong></div><div class="stat"><span>Работа поиска, units</span><strong>${esc(m.used)}</strong></div></div><p class="hint">Расходы поиска не списаны с канонических балансов.</p>${m.truncated?'<p class="notice">Поиск остановлен лимитом. Более выгодные неисследованные кандидаты возможны.</p>':''}${report.decisions.map(d=>{
 const best=d.selected===null?null:d.candidates[d.selected],group=d.bundle?block.scheduler.state.bundles?.[d.bundle.id]:null;
 return `<article class="search-decision"><h3>${esc(d.agent)} · ${esc(d.action)}</h3><p>Trigger ${esc(d.trigger)} · parent block ${esc(d.observed_block)} · реакция ${esc(d.at)} s<br>${esc(d.reason)}${d.prefix?' · prefix '+esc(d.prefix.status):''}</p>${best?`<div class="notice">Выбран вход ${esc(best.input)} ${asset}, путь ${best.hops.map(h=>esc(h.venue)).join(' → ')}. Условный net: <strong>${esc(best.net)} ${asset}</strong> после fees и bid.</div>`:''}${d.bundle?`<p>Группа <code>${esc(d.bundle.id)}</code><br>Цель: блок ${esc(d.bundle.min_block)} · ${group?status(group.status):'не зарегистрирована'}</p>`:''}<details><summary>Кандидаты · ${d.candidates.length}</summary><table><tr><th>Вход / путь</th><th>Исход / условный net</th><th>Units / fees</th></tr>${d.candidates.map((p,i)=>`<tr class="${i===d.selected?'search-best':''}"><td>${esc(p.input)} ${asset}<br>${p.hops.map(h=>esc(h.venue)).join(' → ')}</td><td>${esc(p.outcome)}<br>${p.net===null?'—':esc(p.net)+' '+asset}</td><td>${esc(p.used)} / ${esc(p.fees)}</td></tr>`).join('')}</table></details></article>`;
 }).join('')||'<p>Поисковых реакций в этом блоке нет.</p>'}`;
}
export function renderBundles(run,block) {
 const c=run.scenario.scheduler?.bundles,panel=$('#bundle-panel');panel.hidden=!c;if(!c)return;
 const report=block?.scheduler,state=report?.state,m=report?.metrics;
 $('#bundle-config').innerHTML=`<h2>Группы транзакций · ${esc(run.scenario.scheduler.builder.type)}</h2><p>Выбранная группа исполняется непрерывно. Разрешённый revert сохраняет предыдущие успешные members и свои fee/nonce; запрещённый отклоняет всю пробу.</p><p class="hint">Score = native fees от других senders + исполненный обозначенный bid. Это валовые платежи, не PnL. Bid — последний реальный перевод; произвольное поступление его не заменяет.</p><details><summary>Отправки и бюджеты</summary><p>Members ≤ ${c.limits.members}; probes/раунд ≤ ${c.limits.probes}; member attempts ≤ ${c.limits.probe_members}.</p>${c.emissions.map(e=>`<article><h3>${esc(e.bundle.id)} · отправка ${esc(e.at)} s</h3><p>${esc(e.bundle.agent)} · целевые блоки ${esc(e.bundle.min_block)}–${esc(e.bundle.max_block)} · deadline ${esc(e.bundle.deadline)} s<br>Bid: ${esc(e.bundle.bid)} ${esc(run.scenario.chain.fee_asset)} · payment ${esc(e.bundle.payment_tx_id??'нет')}<br>Разрешённые reverts: ${e.bundle.allowed_reverts.map(esc).join(', ')||'нет'}</p><ol>${e.bundle.members.map(t=>`<li>${t.type==='Own'?`${esc(t.transaction.id)} · ${esc(t.transaction.sender)} · nonce ${esc(t.transaction.nonce)}`:'VisibleTxId · '+esc(t.tx_id)}</li>`).join('')}</ol></article>`).join('')}</details>`;
 if(!report){$('#bundle-result').innerHTML='<p class="muted">Запустите блок, чтобы увидеть admission, пробы и выбор.</p>';return;}
 $('#bundle-result').innerHTML=`<div class="stats"><div class="stat"><span>Пробы / member attempts</span><strong>${m.probes} / ${m.probe_members}</strong></div><div class="stat"><span>Работа проб, units</span><strong>${esc(m.probe_used)}</strong></div><div class="stat"><span>Pending groups</span><strong>${Object.keys(state.bundle_pending??{}).length}</strong></div></div>`+
 (m.truncated?'<p class="notice">Поиск ограничен бюджетом. Непроверенные кандидаты не объявляются невыгодными.</p>':'')+
 `<h3>Статусы групп</h3>${Object.entries(state.bundles??{}).map(([bid,b])=>`<p><strong>${esc(bid)}</strong> · ${status(b.status)}${state.bundle_pending?.[bid]?'<br>Arrival '+esc(state.bundle_pending[bid].arrival)+' s':''}</p>`).join('')||'<p>Группы ещё не отправлены.</p>'}`+
 `<h3>Выбор и пробное исполнение</h3>${(report.probes??[]).map(p=>`<article class="bundle-probe ${p.selected?'picked':''}"><h3>${id(p.candidate)} · ${p.selected?'Включён':'Не выбран'}</h3><p>${esc(p.outcome)} · ${esc(p.mode)}</p><div class="stats"><div class="stat"><span>Score, ${esc(run.scenario.chain.fee_asset)}</span><strong>${valued(p)?esc(p.score):'—'}</strong></div><div class="stat"><span>Fees + bid</span><strong>${valued(p)?esc(p.paid_fees)+' + '+esc(p.bid):'—'}</strong></div><div class="stat"><span>Used, units</span><strong>${esc(p.used)}</strong></div></div><p>Изменение баланса builder: ${valued(p)?(p.builder_delta.negative?'−':'+')+esc(p.builder_delta.magnitude)+' '+esc(run.scenario.chain.fee_asset):'не рассчитано'}</p>${!p.selected?'<p class="hint">Эти пробные receipts и комиссии не вошли в канонический блок. При незавершённой пробе score не рассчитан.</p>':'<p class="hint">Ниже — последовательность канонических receipts выбранного кандидата.</p>'}<details ${p.selected?'open':''}><summary>Транзакции · ${p.receipts.length}</summary><table><tr><th>Tx / sender</th><th>Исход / units / fee</th></tr>${p.receipts.map(r=>`<tr><td><code>${esc(r.tx_id)}</code><br>${esc(r.sender)}</td><td>${esc(r.status)}<br>${esc(r.used)} units · fee ${esc(r.fee)}${r.error?'<br>'+esc(r.error):''}</td></tr>`).join('')}</table></details></article>`).join('')}`;
}
